MODULE2_MATERIALS = [
    {
        "slug": "k-means-theory",
        "title": "Метод K-средних (K-Means)",
        "concept_uri": "Algo_KMeans",
        "order": 110,
        "content": """
<h2>Идея метода</h2>
<p>K-Means — это алгоритм разбиения, который заранее получает число кластеров \\(K\\) и описывает каждый кластер центроидом. Центроид — это не обязательно реальная точка из выборки, а среднее положение объектов внутри группы.</p>
<p>Метод старается сделать кластеры компактными: каждая точка должна быть близка к центроиду своего кластера. Поэтому целевая функция записывается как сумма квадратов расстояний от точек до назначенных центроидов:</p>
<p>$$Q = \\sum_{i=1}^{\\ell} \\|x_i - \\mu_{a_i}\\|^2 \\rightarrow \\min.$$</p>
<p>Здесь \\(x_i\\) — объект, \\(a_i\\) — номер его кластера, \\(\\mu_{a_i}\\) — центроид этого кластера.</p>
<h2>Два чередующихся шага</h2>
<ol>
    <li><strong>Назначение точек.</strong> Для каждой точки выбирается ближайший центроид: $$a_i = \\arg\\min_k \\|x_i - \\mu_k\\|^2.$$</li>
    <li><strong>Пересчет центроидов.</strong> Для каждого кластера считается среднее его точек: $$\\mu_k = \\frac{1}{|C_k|}\\sum_{x_i \\in C_k} x_i.$$</li>
</ol>
<p>Эти шаги повторяются, пока назначения почти не меняются или пока не достигнут лимит итераций. На каждой итерации значение \\(Q\\) не увеличивается, поэтому алгоритм обычно быстро стабилизируется.</p>
<h2>Что важно понимать</h2>
<p>K-Means не перебирает все возможные разбиения. Он улучшает текущее решение, поэтому результат зависит от начальных центроидов и может оказаться локальным оптимумом. На практике алгоритм запускают несколько раз с разными инициализациями и выбирают разбиение с меньшей суммой квадратов.</p>
""".strip(),
    },
    {
        "slug": "kmeans-initialization-and-limits",
        "title": "Инициализация и ограничения K-Means",
        "concept_uri": "Algo_KMeans",
        "order": 120,
        "content": """
<h2>Почему старт важен</h2>
<p>K-Means начинает работу с начальных центроидов. Если они выбраны неудачно, два центра могут попасть в одну реальную группу, а другая группа останется без представителя. Тогда алгоритм все равно сойдется, но итоговое разбиение может быть хуже.</p>
<p>Поэтому в практических реализациях используют несколько запусков или более аккуратную инициализацию, которая старается разнести начальные центры по данным.</p>
<h2>Пустые кластеры</h2>
<p>Иногда после шага назначения у центроида не остается ни одной точки. Такой кластер нельзя пересчитать как среднее. Обычно его переинициализируют: например, переносят центр в далекую точку или в точку с большой ошибкой.</p>
<h2>Когда K-Means подходит</h2>
<p>Метод хорошо работает, когда группы похожи на компактные облака, имеют сопоставимый масштаб и разделяются по евклидову расстоянию. Он особенно удобен как быстрый базовый метод и как первый ориентир для анализа данных.</p>
<h2>Когда стоит насторожиться</h2>
<ul>
    <li>кластеры имеют форму колец, спиралей или вытянутых лент;</li>
    <li>признаки измерены в сильно разных масштабах;</li>
    <li>в данных много выбросов;</li>
    <li>число кластеров заранее неизвестно;</li>
    <li>кластеры имеют очень разную плотность или размер.</li>
</ul>
<p>В таких случаях результат K-Means нужно проверять особенно внимательно и часто сравнивать с другими алгоритмами.</p>
""".strip(),
    },
    {
        "slug": "minibatch-kmeans-theory",
        "title": "MiniBatch K-Means",
        "concept_uri": "Algo_MiniBatchKMeans",
        "order": 130,
        "content": """
<h2>Зачем нужен MiniBatch</h2>
<p>Обычный K-Means на каждой итерации просматривает всю выборку. Если объектов очень много, это становится вычислительно дорогим шагом. MiniBatch K-Means ускоряет обучение: на каждом шаге он берет не все данные, а небольшую случайную порцию объектов — мини-батч.</p>
<h2>Как меняется пересчет центра</h2>
<p>Вместо полного пересчета центроида по всем точкам кластера алгоритм постепенно сдвигает центр в сторону среднего мини-батча:</p>
<p>$$\\mu_k^{new} = \\mu_k^{old} + \\eta(\\bar{x}_k - \\mu_k^{old}).$$</p>
<p>Здесь \\(\\bar{x}_k\\) — среднее точек мини-батча, назначенных кластеру \\(k\\), а \\(\\eta\\) — скорость обновления.</p>
<h2>Компромисс</h2>
<p>MiniBatch обычно работает быстрее и лучше подходит для больших наборов данных, но результат может быть немного менее стабильным, чем у полного K-Means. Размер батча влияет на баланс: маленький батч быстрее, но шумнее; большой батч надежнее, но дороже.</p>
""".strip(),
    },
    {
        "slug": "bisecting-kmeans-theory",
        "title": "Bisecting K-Means",
        "concept_uri": "Algo_BisectingKMeans",
        "order": 140,
        "content": """
<h2>Идея нисходящего разбиения</h2>
<p>Bisecting K-Means соединяет идею K-Means и иерархического подхода. Вместо того чтобы сразу искать \\(K\\) кластеров, алгоритм начинает с одного большого кластера и последовательно делит выбранный кластер на две части с помощью K-Means при \\(K=2\\).</p>
<h2>Типичный порядок работы</h2>
<ol>
    <li>Поместить все объекты в один кластер.</li>
    <li>Выбрать кластер для разбиения. Часто выбирают самый большой кластер или тот, у которого выше сумма квадратов ошибок.</li>
    <li>Разделить выбранный кластер на две части с помощью K-Means с \\(K=2\\).</li>
    <li>Повторять, пока не получится нужное число кластеров.</li>
</ol>
<h2>Где это полезно</h2>
<p>Такой подход удобен, когда нужна не только финальная группировка, но и логика постепенного деления данных. Он часто хорошо подходит для крупных наборов объектов, например текстов или документов, где логично идти от общей группы к более узким темам.</p>
""".strip(),
    },
]

MODULE2_MATERIALS.extend([
    {
        "slug": "kmeans-objective-and-inertia",
        "title": "Целевая функция K-Means и инерция",
        "concept_uri": "QualityCriterion",
        "order": 115,
        "content": """
<h2>Что именно минимизирует K-Means</h2>
<p>K-Means строит разбиение с центроидами и оценивает его через сумму квадратов расстояний от объектов до центроидов своих кластеров. Эту величину часто называют внутрикластерной суммой квадратов, SSE или инерцией (inertia).</p>
<p>Если \\(a_i\\) — номер кластера объекта \\(x_i\\), а \\(\\mu_{a_i}\\) — центроид этого кластера, то критерий имеет вид:</p>
<p>$$Q = \\sum_{i=1}^{\\ell} \\|x_i - \\mu_{a_i}\\|^2.$$</p>
<p>Чем меньше \\(Q\\), тем компактнее получившиеся кластеры относительно своих центроидов. Это не универсальная мера качества всей кластеризации, но именно ее оптимизирует K-Means.</p>
<h2>Почему используется квадрат расстояния</h2>
<p>Квадрат расстояния сильнее штрафует далекие точки. Поэтому выбросы и плохо назначенные объекты могут заметно повлиять на положение центроида и значение критерия.</p>
<h2>Критерий не равен смыслу</h2>
<p>Низкая инерция означает, что точки близки к центроидам, но не гарантирует, что найденные группы полезны для предметной задачи. Разбиение нужно проверять визуально, через интерпретацию признаков и дополнительные метрики качества.</p>
<h2>Как используется инерция</h2>
<ul>
    <li>сравнить несколько запусков K-Means с разными начальными центрами;</li>
    <li>проверить, насколько заметно улучшается решение при увеличении \\(K\\);</li>
    <li>найти подозрительные случаи, где ошибка велика из-за формы данных, выбросов или масштаба признаков.</li>
</ul>
""".strip(),
    },
    {
        "slug": "choosing-number-of-clusters",
        "title": "Выбор числа кластеров K",
        "concept_uri": "Param_NumClusters",
        "order": 125,
        "content": """
<h2>Почему K задается заранее</h2>
<p>В классическом K-Means число кластеров \\(K\\) является параметром. Алгоритм не доказывает, сколько групп реально существует в данных; он строит лучшее разбиение при заданном \\(K\\).</p>
<p>Из-за этого один и тот же набор объектов можно разбить на разное число групп. Иногда два крупных сегмента полезнее пяти мелких, а иногда наоборот: мелкие группы позволяют принимать более точечные решения.</p>
<h2>Идея локтя</h2>
<p>Один из базовых подходов — посчитать инерцию для нескольких значений \\(K\\). При увеличении \\(K\\) ошибка обычно падает, потому что центроидов становится больше. Но после некоторого момента выигрыш может резко замедлиться.</p>
<p>Если график ошибки сначала быстро падает, а затем становится пологим, точку перегиба условно называют локтем. Это не строгое доказательство, но полезная гипотеза о числе кластеров.</p>
<h2>Что еще учитывать</h2>
<ul>
    <li>интерпретируемость сегментов;</li>
    <li>стабильность результата при разных запусках;</li>
    <li>размеры кластеров и наличие почти пустых групп;</li>
    <li>цель анализа: обзор, сжатие данных, сегментация клиентов или дальнейшая модель.</li>
</ul>
<p>Хороший выбор \\(K\\) — это компромисс между математическим критерием и смыслом задачи.</p>
""".strip(),
    },
    {
        "slug": "kmeans-shape-size-and-scale",
        "title": "Форма, размер и масштаб кластеров",
        "concept_uri": "FlatGeometry",
        "order": 128,
        "content": """
<h2>Какие формы любит K-Means</h2>
<p>K-Means особенно хорошо работает, когда кластеры похожи на компактные облака вокруг центроидов. В таком случае границы между кластерами возникают естественно: каждая точка попадает к ближайшему центру.</p>
<p>Если естественные группы имеют форму колец, лент или дуг, центроидный подход может разрезать их поперек. Это не ошибка реализации, а ограничение модели разбиения.</p>
<h2>Размеры кластеров</h2>
<p>Если один кластер намного больше или плотнее другого, K-Means может смещать границы так, чтобы уменьшить сумму квадратов, а не сохранить содержательно ожидаемые группы. Поэтому равномерность размеров кластеров не является обязательной целью, но сильная неравномерность требует диагностики.</p>
<h2>Масштаб признаков</h2>
<p>Евклидово расстояние чувствительно к масштабу. Если один признак измеряется в тысячах, а другой в единицах, большой признак может доминировать в расстоянии и фактически управлять разбиением.</p>
<p>Перед K-Means обычно проверяют масштабирование признаков и смысл того, какие различия должны считаться важными.</p>
""".strip(),
    },
    {
        "slug": "kmeans-as-data-reduction",
        "title": "K-Means как сжатие данных",
        "concept_uri": "UC_DataReduction",
        "order": 145,
        "content": """
<h2>Центроид как представитель</h2>
<p>После обучения K-Means каждый кластер можно заменить его центроидом. Это дает простую идею сжатия: вместо всех объектов хранить несколько типичных представителей и информацию о том, к какому представителю относится каждый объект.</p>
<p>Такой подход называют векторным квантованием. Он полезен, когда нужно приблизить большое множество точек небольшим набором прототипов.</p>
<h2>Что теряется</h2>
<p>Центроид является средним, поэтому он сглаживает индивидуальные различия объектов. Если внутри кластера есть сложная форма или несколько подгрупп, один центр может описывать их слишком грубо.</p>
<h2>Когда это полезно</h2>
<ul>
    <li>быстро получить прототипы групп;</li>
    <li>уменьшить объем данных для визуализации;</li>
    <li>сжать похожие векторы признаков;</li>
    <li>получить базовые сегменты для дальнейшего анализа.</li>
</ul>
""".strip(),
    },
])

MODULE2_MATERIALS.extend([
    {
        "slug": "kmeans-plus-plus-initialization",
        "title": "k-means++: аккуратная инициализация центров",
        "concept_uri": "Algo_KMeans",
        "order": 122,
        "content": """
<h2>Почему случайный старт может быть плохим</h2>
<p>K-Means чувствителен к начальному выбору центроидов. Если несколько центров случайно попали в одну и ту же реальную группу, алгоритм может сойтись к слабому локальному решению: часть данных будет плохо представлена, а инерция окажется выше.</p>
<h2>Идея k-means++</h2>
<p>k-means++ выбирает первый центр случайно, а следующие старается брать дальше от уже выбранных центров. Для каждой точки считается квадрат расстояния до ближайшего уже выбранного центра. Чем это расстояние больше, тем выше шанс, что точка станет новым центром.</p>
<p>Интуитивно это заставляет стартовые центры покрывать разные области данных, а не скапливаться в одном месте.</p>
<h2>Практический смысл</h2>
<p>Такая инициализация не делает K-Means идеальным и не отменяет ограничений метода, но обычно дает более стабильный старт и снижает риск плохого локального минимума. Поэтому современные реализации часто используют k-means++ по умолчанию или как рекомендуемый вариант.</p>
""".strip(),
    },
    {
        "slug": "silhouette-and-k-choice",
        "title": "Выбор K: elbow и силуэт",
        "concept_uri": "QMetric_SilhouetteScore",
        "order": 126,
        "content": """
<h2>Почему одной инерции мало</h2>
<p>Инерция K-Means почти всегда уменьшается при увеличении числа кластеров \\(K\\): чем больше центроидов, тем легче приблизить точки. Поэтому минимальная инерция сама по себе не говорит, что выбранное \\(K\\) является содержательно лучшим.</p>
<h2>Метод локтя</h2>
<p>Метод локтя смотрит на график инерции при разных \\(K\\). Если после некоторого значения улучшение становится заметно слабее, это значение рассматривают как разумный компромисс между простотой и компактностью.</p>
<h2>Силуэт как дополнительная проверка</h2>
<p>Силуэт оценивает, насколько объекты близки к своему кластеру и далеко от ближайшего чужого. Поэтому он помогает проверить не только компактность вокруг центроидов, но и отделенность групп.</p>
<p>На практике полезно смотреть оба сигнала: elbow показывает, где инерция перестает резко падать, а силуэт помогает понять, не стало ли разбиение формальным и плохо отделенным.</p>
""".strip(),
    },
])

