MODULE4_MATERIALS = [
    {
        "slug": "hierarchical-clustering-intuition",
        "title": "Иерархическая кластеризация: вложенные группы",
        "concept_uri": "HierarchicalAlgorithm",
        "order": 310,
        "content": """
<h2>Зачем нужна иерархия</h2>
<p>В предыдущих модулях результат обычно был одним разбиением: каждому объекту назначалась одна итоговая группа. Иерархическая кластеризация строит не одно разбиение, а систему вложенных кластеров. Это полезно, когда данные можно рассматривать на разных уровнях детализации: сначала крупные группы, затем подгруппы внутри них.</p>
<p>Например, коллекцию документов можно сначала разделить на технические и гуманитарные тексты, затем внутри технических выделить машинное обучение, базы данных и сети, а внутри машинного обучения — кластеризацию, классификацию и регрессию.</p>
<h2>Два направления построения</h2>
<ul>
    <li><strong>Агломеративный подход</strong>: начать с отдельных объектов и постепенно объединять ближайшие кластеры.</li>
    <li><strong>Дивизимный подход</strong>: начать со всей выборки и постепенно делить крупные кластеры на части.</li>
</ul>
<p>В этом модуле основной акцент сделан на агломеративной схеме: она проще для визуального понимания, хорошо связана с матрицей расстояний и естественно приводит к дендрограмме.</p>
<h2>Связь с предыдущими модулями</h2>
<p>Иерархические методы продолжают тему расстояний из первого модуля, отличаются от K-Means тем, что не требуют заранее фиксировать центроиды, и дополняют плотностные методы: вместо локального роста плотной области они строят всю историю объединения объектов.</p>
""".strip(),
    },
    {
        "slug": "agglomerative-clustering-algorithm",
        "title": "Агломеративный алгоритм",
        "concept_uri": "Algo_Agglomerative",
        "order": 320,
        "content": """
<h2>Основной порядок работы</h2>
<p>Агломеративная кластеризация начинает с максимально подробного состояния: каждый объект является отдельным кластером. Затем алгоритм много раз объединяет два ближайших кластера, пока не останется один общий кластер или пока пользователь не остановит процесс на нужном числе групп.</p>
<ol>
    <li>Построить начальную матрицу расстояний между объектами.</li>
    <li>Считать каждый объект отдельным кластером.</li>
    <li>Найти пару кластеров с минимальным расстоянием.</li>
    <li>Объединить эту пару в новый кластер.</li>
    <li>Пересчитать расстояния от нового кластера до остальных.</li>
    <li>Повторять, пока не будет получена вся иерархия.</li>
</ol>
<h2>Главный вопрос</h2>
<p>После первого объединения в системе появляются кластеры, состоящие из нескольких объектов. Поэтому нужно определить, что такое расстояние между двумя кластерами. Ответ на этот вопрос называется linkage-критерием.</p>
<h2>Почему это не K-Means</h2>
<p>Агломеративный алгоритм не двигает центроиды на каждой итерации и не перебирает назначения точек. Он принимает последовательность локальных решений: какие два кластера сейчас ближе всего. Уже сделанное объединение обычно не отменяется, поэтому ранние решения могут влиять на всю дальнейшую структуру.</p>
""".strip(),
    },
    {
        "slug": "linkage-criteria",
        "title": "Расстояния между кластерами: linkage",
        "concept_uri": "Metric_NearestPointDistance",
        "order": 330,
        "content": """
<h2>Зачем нужен linkage</h2>
<p>Когда кластер состоит из нескольких объектов, расстояние между кластерами уже нельзя прочитать как расстояние между двумя точками. Нужно выбрать правило, которое сводит множество попарных расстояний к одному числу.</p>
<h2>Single linkage</h2>
<p>Расстояние между кластерами равно минимальному расстоянию между их объектами:</p>
<p>$$d_{single}(A,B)=\\min_{x\\in A, y\\in B}\\rho(x,y).$$</p>
<p>Этот критерий хорошо находит связные цепочки, но может страдать от эффекта цепи: отдельные близкие мостики склеивают большие группы.</p>
<h2>Complete linkage</h2>
<p>Расстояние равно максимальному расстоянию между объектами двух кластеров:</p>
<p>$$d_{complete}(A,B)=\\max_{x\\in A, y\\in B}\\rho(x,y).$$</p>
<p>Такой критерий обычно стремится к более компактным кластерам и осторожнее объединяет вытянутые группы.</p>
<h2>Average linkage</h2>
<p>Расстояние равно среднему попарному расстоянию между объектами разных кластеров:</p>
<p>$$d_{average}(A,B)=\\frac{1}{|A||B|}\\sum_{x\\in A}\\sum_{y\\in B}\\rho(x,y).$$</p>
<p>Это компромисс между ближайшим и дальним соседом: он учитывает все пары, а не только экстремальное расстояние.</p>
""".strip(),
    },
    {
        "slug": "lance-williams-update",
        "title": "Формула Ланса-Уильямса",
        "concept_uri": "HierarchicalAlgorithm",
        "order": 340,
        "content": """
<h2>Зачем нужна формула пересчета</h2>
<p>После объединения кластеров \\(A\\) и \\(B\\) нужно быстро найти расстояние от нового кластера \\(A\\cup B\\) до любого другого кластера \\(C\\). Многие агломеративные методы можно записать через общую формулу пересчета расстояний.</p>
<p>Один из распространенных вариантов записи:</p>
<p>$$d(A\\cup B,C)=\\alpha_A d(A,C)+\\alpha_B d(B,C)+\\beta d(A,B)+\\gamma |d(A,C)-d(B,C)|.$$</p>
<p>Разные значения коэффициентов дают разные linkage-критерии. Поэтому формула удобна как общий язык для описания агломеративных методов.</p>
<h2>Интуитивный смысл</h2>
<p>Формула показывает, что расстояние до нового кластера можно получить из уже известных расстояний: до \\(A\\), до \\(B\\), между \\(A\\) и \\(B\\), а иногда и из разницы расстояний до \\(C\\). Это позволяет не пересчитывать все попарные расстояния с нуля.</p>
<h2>Почему это важно для понимания</h2>
<p>Студенту не нужно заучивать все коэффициенты. Важно увидеть, что single, complete, average и Ward — не случайные отдельные рецепты, а разные правила обновления одной и той же иерархической процедуры.</p>
""".strip(),
    },
    {
        "slug": "ward-method-theory",
        "title": "Метод Уорда",
        "concept_uri": "Algo_Ward",
        "order": 350,
        "content": """
<h2>Идея метода</h2>
<p>Метод Уорда — агломеративный иерархический метод, который выбирает объединение не просто по ближайшей паре точек, а по тому, насколько объединение увеличит внутрикластерную сумму квадратов. Он близок по духу к K-Means: оба метода любят компактные группы и работают с идеей внутрикластерного разброса.</p>
<h2>Стоимость объединения</h2>
<p>Если у кластеров \\(A\\) и \\(B\\) размеры \\(|A|\\), \\(|B|\\), а их центроиды равны \\(\\mu_A\\) и \\(\\mu_B\\), то увеличение критерия можно записать так:</p>
<p>$$\\Delta(A,B)=\\frac{|A||B|}{|A|+|B|}\\|\\mu_A-\\mu_B\\|^2.$$</p>
<p>Алгоритм объединяет ту пару кластеров, для которой \\(\\Delta\\) минимально.</p>
<h2>Когда метод хорош</h2>
<p>Метод Уорда часто дает понятные компактные кластеры и хорошо подходит для числовых признаков после масштабирования. Он особенно полезен, когда нужно получить иерархию, но при этом сохранить связь с критерием компактности.</p>
<h2>Ограничения</h2>
<p>Метод чувствителен к масштабу признаков и выбросам. Если данные имеют сложную невыпуклую форму, Ward может вести себя похоже на центроидные методы: стремиться к компактным группам, а не к длинным связным областям.</p>
""".strip(),
    },
    {
        "slug": "dendrogram-reading",
        "title": "Как читать дендрограмму",
        "concept_uri": "HierarchicalAlgorithm",
        "order": 360,
        "content": """
<h2>Что показывает дендрограмма</h2>
<p>Дендрограмма — это визуальная запись истории объединения кластеров. Внизу обычно находятся отдельные объекты, выше — объединения, а вертикальная высота показывает расстояние или стоимость объединения.</p>
<h2>Как выбирать число кластеров</h2>
<p>Чтобы получить обычное разбиение из иерархии, дендрограмму мысленно разрезают горизонтальной линией. Сколько вертикальных ветвей пересекает линия, столько кластеров получается на этом уровне.</p>
<p>Часто выбирают уровень перед большим скачком высоты: если следующее объединение происходит намного выше предыдущих, значит алгоритм собирается объединить уже достаточно разные группы.</p>
<h2>Что важно не перепутать</h2>
<ul>
    <li>Порядок листьев слева направо не является шкалой расстояния между соседними объектами.</li>
    <li>Высота объединения важнее горизонтального положения ветвей.</li>
    <li>Разные linkage-критерии могут дать разные дендрограммы на одних и тех же данных.</li>
    <li>Дендрограмма помогает выбрать уровень детализации, но не заменяет интерпретацию кластеров.</li>
</ul>
""".strip(),
    },
    {
        "slug": "hierarchical-methods-practice",
        "title": "Когда применять иерархические методы",
        "concept_uri": "QualityCriterion",
        "order": 370,
        "content": """
<h2>Сильные стороны</h2>
<p>Иерархическая кластеризация полезна, когда нужно не только получить группы, но и увидеть, как они вложены друг в друга. Она хорошо подходит для исследовательского анализа, небольших и средних выборок, таксономий, группировки документов, биологических объектов и любых случаев, где важна структура уровней.</p>
<h2>Практические преимущества</h2>
<ul>
    <li>не нужно заранее выбирать единственное число кластеров;</li>
    <li>можно сравнивать разные уровни детализации;</li>
    <li>дендрограмма дает понятное объяснение результата;</li>
    <li>разные linkage-критерии позволяют менять характер кластеров.</li>
</ul>
<h2>Ограничения</h2>
<p>Агломеративные методы обычно дороже по памяти и времени, чем K-Means. Кроме того, ранние объединения не пересматриваются: если алгоритм неудачно склеил две группы в начале, дальше это решение останется внутри иерархии.</p>
<h2>Как выбирать критерий</h2>
<p>Single linkage подходит, когда важна связность и допустимы вытянутые цепочки. Complete linkage дает более компактные группы. Average linkage является спокойным компромиссом. Ward хорошо подходит для числовых данных, когда нужен критерий компактности и признаки корректно масштабированы.</p>
""".strip(),
    },
]


