MODULE5_MATERIALS = [
    {
        "slug": "gmm-soft-clustering",
        "title": "Gaussian Mixture Models: мягкая кластеризация",
        "concept_uri": "Algo_GaussianMixtures",
        "order": 410,
        "content": """
<h2>От жестких меток к вероятностям</h2>
<p>В K-Means каждая точка принадлежит ровно одному кластеру. Gaussian Mixture Model, или GMM, описывает данные как смесь нескольких распределений. Вместо жесткой метки модель оценивает вероятность принадлежности объекта к каждой компоненте.</p>
<p>Если объект лежит между двумя группами, GMM может показать неопределенность: например, \\(0.55\\) для первой компоненты и \\(0.45\\) для второй. Это называют мягкой кластеризацией.</p>
<h2>Модель смеси</h2>
<p>Плотность данных записывается как сумма компонент:</p>
<p>$$p(x)=\\sum_{k=1}^{K}\\pi_k\\mathcal{N}(x|\\mu_k,\\Sigma_k).$$</p>
<p>Здесь \\(\\pi_k\\) — вес компоненты, \\(\\mu_k\\) — средний вектор, \\(\\Sigma_k\\) — ковариационная матрица. В отличие от K-Means, компоненте можно задавать не только центр, но и форму: вытянутость, направление и разброс.</p>
<h2>Когда GMM полезен</h2>
<ul>
    <li>кластеры похожи на эллиптические облака;</li>
    <li>нужна вероятность принадлежности, а не только метка;</li>
    <li>важно видеть неопределенность на границах кластеров;</li>
    <li>данные можно разумно описывать смесью распределений.</li>
</ul>
""".strip(),
    },
    {
        "slug": "em-for-gaussian-mixtures",
        "title": "EM-алгоритм для GMM",
        "concept_uri": "Algo_GaussianMixtures",
        "order": 420,
        "content": """
<h2>Почему нужен EM</h2>
<p>В GMM неизвестны и параметры компонент, и то, какая компонента породила каждый объект. EM-алгоритм решает эту задачу чередованием двух шагов: сначала оценивает скрытые принадлежности, затем обновляет параметры компонент.</p>
<h2>E-шаг</h2>
<p>На E-шаге для каждого объекта вычисляются ответственности компонент — вероятности того, что объект относится к каждой компоненте:</p>
<p>$$r_{ik}=P(k|x_i).$$</p>
<p>Для каждого объекта суммы ответственностей по всем компонентам равны единице.</p>
<h2>M-шаг</h2>
<p>На M-шаге параметры компонент пересчитываются с учетом ответственностей. Например, среднее компоненты можно записать как взвешенное среднее:</p>
<p>$$\\mu_k=\\frac{\\sum_i r_{ik}x_i}{\\sum_i r_{ik}}.$$</p>
<h2>Связь с K-Means</h2>
<p>K-Means можно воспринимать как более жесткий частный случай идеи: точка полностью относится к одному центру. GMM сохраняет больше информации, потому что хранит степени принадлежности.</p>
""".strip(),
    },
    {
        "slug": "spectral-clustering-graph",
        "title": "Spectral Clustering: кластеризация через граф",
        "concept_uri": "Algo_SpectralClustering",
        "order": 430,
        "content": """
<h2>Переход от точек к графу</h2>
<p>Спектральная кластеризация строит граф похожести: объекты становятся вершинами, а ребра показывают, насколько объекты близки. Чем сильнее похожи две точки, тем больше вес ребра между ними.</p>
<p>Часто похожесть задают через RBF-ядро:</p>
<p>$$w_{ij}=\\exp(-\\gamma\\|x_i-x_j\\|^2).$$</p>
<h2>Зачем нужен граф</h2>
<p>Граф позволяет находить группы не только по близости к центрам, но и по связности. Поэтому спектральный подход полезен для колец, лун и других форм, где обычное центроидное разбиение может ошибаться.</p>
<h2>Общая схема</h2>
<ol>
    <li>Построить матрицу похожести между объектами.</li>
    <li>Построить графовый лапласиан.</li>
    <li>Получить спектральное вложение через собственные векторы.</li>
    <li>Кластеризовать точки уже в новом пространстве, часто с помощью K-Means.</li>
</ol>
<p>В модуле важно понять идею: иногда сначала нужно изменить представление данных, и только потом применять обычный алгоритм разбиения.</p>
""".strip(),
    },
    {
        "slug": "affinity-propagation-exemplars",
        "title": "Affinity Propagation: представители через сообщения",
        "concept_uri": "Algo_AffinityPropagation",
        "order": 440,
        "content": """
<h2>Идея представителей</h2>
<p>Affinity Propagation ищет не центроид как среднюю точку, а реальные объекты-представители, которые называются exemplars. Каждый кластер описывается одним таким представителем.</p>
<h2>Как происходит выбор</h2>
<p>Метод работает через обмен сообщениями между точками. Одни сообщения оценивают, насколько точка подходит быть представителем для другой, другие — насколько разумно выбрать конкретную точку представителем с учетом конкуренции.</p>
<h2>Чем это отличается от K-Means</h2>
<p>K-Means требует заранее задать \\(K\\), а Affinity Propagation может сам выбрать число представителей через параметр предпочтения. При этом представитель является реальным объектом из выборки, а не усредненным центроидом.</p>
<h2>Когда это полезно</h2>
<p>Метод удобен, когда важно получить типичные реальные примеры кластеров: документы, товары, изображения, профили пользователей. Но он может быть дорогим по памяти, потому что работает с матрицей похожести между объектами.</p>
""".strip(),
    },
    {
        "slug": "birch-cf-tree",
        "title": "BIRCH: микрокластеры и CF-дерево",
        "concept_uri": "Algo_BIRCH",
        "order": 450,
        "content": """
<h2>Зачем нужен BIRCH</h2>
<p>BIRCH предназначен для больших наборов данных. Вместо того чтобы постоянно хранить и сравнивать все точки, он постепенно сжимает данные в компактные микрокластеры.</p>
<h2>Clustering Feature</h2>
<p>Микрокластер можно описать тройкой CF:</p>
<p>$$CF=(N, LS, SS).$$</p>
<p>Здесь \\(N\\) — число точек, \\(LS\\) — покоординатная сумма точек, \\(SS\\) — покоординатная сумма квадратов. По этим величинам можно быстро получить центр и оценить разброс микрокластера.</p>
<h2>CF-дерево</h2>
<p>BIRCH строит дерево микрокластеров. Новые точки добавляются в ближайший подходящий микрокластер, если его радиус не превышает порог. Если микрокластер становится слишком широким, структура дерева перестраивается.</p>
<h2>Практический смысл</h2>
<p>BIRCH полезен как предварительное сжатие больших данных: сначала строятся микрокластеры, а затем уже их можно дополнительно кластеризовать другим методом.</p>
""".strip(),
    },
    {
        "slug": "module5-method-choice",
        "title": "Когда выбирать методы пятого модуля",
        "concept_uri": "QualityCriterion",
        "order": 460,
        "content": """
<h2>Как выбирать метод</h2>
<p>Методы пятого модуля показывают, что кластеризация может быть не только центроидной, плотностной или иерархической. Иногда полезнее описывать данные вероятностно, строить граф похожести, искать реальные представители или сжимать поток точек в микрокластеры.</p>
<ul>
    <li><strong>GMM</strong> — когда нужны мягкие вероятности и эллиптические компоненты.</li>
    <li><strong>Spectral Clustering</strong> — когда важна связность и сложная форма данных.</li>
    <li><strong>Affinity Propagation</strong> — когда нужны реальные представители кластеров и число групп не задано заранее.</li>
    <li><strong>BIRCH</strong> — когда данных много и нужно сначала сжать их в микрокластеры.</li>
</ul>
<h2>Общее ограничение</h2>
<p>Эти методы сильнее, но не универсальны. GMM зависит от предположений о распределении, spectral и affinity часто требуют матрицу похожести, BIRCH зависит от порога микрокластера. Поэтому выбор метода всегда связан с формой данных, масштабом выборки и целью анализа.</p>
""".strip(),
    },
]


